head.script:
// 테스트 설명, 유효성 값 설정
//  - column 샘플 관례 : hiddenClass 는 Body Column 에만 설정 (설정 영역 con 옵션 미생성)
//    "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." validation 은 제외
//  - GridView 단위 hiddenClass 는 가이드 숨김 옵션이라 사용하지 않음
scwin.tData = {
    "description" : "[column > P > hiddenClass]<br/>Column 이 숨김 상태일때 적용할 CSS 클래스를 설정합니다.",
    "validation" : [
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정합니다.",
        "속성값은 해당 Column 과 연결된 Header Column 에도 적용됩니다.",
        "설정한 클래스는 기존 class 에 추가되어 적용됩니다.",
        "hidden='true' 로 설정된 Column 은 화면이 처음 그려질 때 클래스가 적용됩니다.",
        "setColumnVisible() 메소드로 Column 을 숨기면 클래스가 적용되고, 다시 표시하면 적용된 클래스가 제거됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean : 1=미설정 / 2=true / 3=false)
    con_hiddenClass.setSelectedIndex(1);
    con_hidden.setValue("2");
    par_columnInfo.setValue("col2");
    par_columnVisible.setValue("false");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 확인 대상 Column (Header Column id / Body Column id)
scwin.colInfo = [
    { "header" : "column1", "body" : "col1" },
    { "header" : "column2", "body" : "col2" },
    { "header" : "column3", "body" : "col3" },
    { "header" : "column4", "body" : "col4" }
];



// comp 생성
//  - col1 : hiddenClass(con 값) + hidden(con 값)  -> 처음 그려질 때 적용
//  - col2 : hiddenClass(con 값), hidden 미설정    -> setColumnVisible() 로 숨김/표시
//  - col3, col4 : hiddenClass 미설정 (대조)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cClass = con_hiddenClass.getValue();
    let cHidden = con_hidden.getText();
    let attrClass = (cClass !== '') ? ' hiddenClass="' + cClass + '"' : '';
    let attrHidden = (cHidden !== '') ? ' hidden="' + cHidden + '"' : '';

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] hiddenClass 는 col1, col2 에만 설정, hidden 은 col1 에만 설정 (col3, col4 는 둘 다 미설정)\n[확인] 클래스 확인 버튼으로 Column 별 Header / Body(0 행) Cell 의 class 와 Body 배경색 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:180px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""' + attrClass + attrHidden + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// class 문자열 (공백 정리)
scwin.getClassText = function (el) {
    if (!el) {
        return "(Cell 없음)";
    }
    return el.className.split(/\s+/).filter(function (c) {
        return c !== "";
    }).join(" ");
}



// Column 별 Header / Body(0 행) Cell 의 class 와 Body 배경색 출력
scwin.printClass = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let prefix = target1.id + "_";
    for (let i = 0; i < scwin.colInfo.length; i++) {
        let th = document.querySelector("[id='" + prefix + scwin.colInfo[i].header + "']");
        let td = document.querySelector("td[id='" + prefix + "cell_0_" + i + "']");
        let bg = td ? window.getComputedStyle(td).backgroundColor : "-";
        // validation 1 ~ 5 판정 출력 : 숨김 상태 Column 의 Header / Body 에 클래스 추가 여부, 기존 class 유지 여부
        bottom.setReturnValue(scwin.colInfo[i].body + " (숨김 " + !target1.getColumnVisible(scwin.colInfo[i].body) + ") : Header = " + scwin.getClassText(th) + " / Body = " + scwin.getClassText(td) + " / Body 배경색 = " + bg);
    }
}



// validation 1 ~ 4 판정 출력 : 현재 class 확인
scwin.btn_checkClass_onclick = function () {
    scwin.printClass();
}



// validation 5 판정 출력 : setColumnVisible(columnInfo, columnVisible) 실행 후 class 확인
scwin.btn_setColumnVisible_onclick = function () {
    let columnInfo = par_columnInfo.getValue();
    let columnVisible = (par_columnVisible.getValue() === "true");
    target1.setColumnVisible(columnInfo, columnVisible);
    wf_body_bottom.getObj("scwin").setReturnValue("setColumnVisible(" + columnInfo + ", " + columnVisible + ") 실행");
    // 화면 갱신이 실행 직후 비동기로 처리되므로 갱신 후 출력
    setTimeout(function () {
        scwin.printClass();
    }, 100);
}
